        def horizontal_mirror(t):
            return [row[::-1] for row in t]

        def distance(a, b):
            return sum(a[r][c] != b[r][c] for r in range(4) for c in range(4))

        # Mark the panel whose layout differs more from its partner's mirror.
        dl = distance(left, horizontal_mirror(right))
        dr = distance(right, horizontal_mirror(left))
        colors = [2, 2]
        if dl != dr:
            colors = [8, 2] if dl < dr else [2, 8]
        elif sum(v == 2 for row in left for v in row) != sum(v == 2 for row in right for v in row):
            colors = [3, 2] if sum(v == 2 for row in left for v in row) > sum(v == 2 for row in right for v in row) else [2, 3]

        for c0, tile, color in ((1, left, colors[0]), (6, right, colors[1])):
            for r in range(4):
                for c in range(4):
                    if tile[r][c] == 2:
                        out[r0+r][c0+c] = color
